    11	void ICommand::printHelpMessage() const
    12	{
    13	    std::cout << "Command: " << command_name << '\n';
    14	    std::cout << "Description: " << description << '\n';
    15	    std::cout << "Usage: " << usage << '\n';
    16	
    17	    if (command_option_description)
    18	    {
    19	        auto options = *command_option_description;
    20	        if (!options.options().empty())
    21	            std::cout << options << '\n';
    22	    }
    23	}
    24	
    25	void ICommand::addOptions(ProgramOptionsDescription & options_description)
    26	{
    27	    if (!command_option_description || command_option_description->options().empty())
    28	        return;
    29	
    30	    options_description.add(*command_option_description);
    31	}
